const res = $input.first().json;
const store = $getWorkflowStaticData('global');
store.chats ??= {};

const text = (res.content || []).filter((part) => part.type === 'text').map((part) => part.text).join('');
let out = null;
try { out = JSON.parse(text); } catch {
  const m = text.match(/\{[\s\S]*\}/);
